const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const eventType = input.event_type || (input.overdue_days >= 2 ? 'recurring.adherence_risk_detected' : 'recurring.reminder_24h');
const isApproved = (input.plan_status === 'ACTIVE_APPROVED' || input.clinical_authorization_status === 'APPROVED' || input.status === 'ACTIVE');
const overdue = Number(input.overdue_days || 0);
const hasAdherenceRisk = isApproved && (overdue >= 2 || eventType === 'recurring.adherence_risk_detected' || eventType === 'recurring.occurrence_missed');

let isNotificationEligible = false;
let templateCode = 'vet_recurring_session_reminder';
let alertSummary = '';

switch (eventType) {
  case 'recurring.adherence_risk_detected':
  case 'recurring.occurrence_missed':
    isNotificationEligible = true;
    templateCode = 'vet_recurring_abandonment_alert';
    alertSummary = 'Alerta de adherencia/visita perdida para paciente ' + (input.pet_name || 'mascota') + ': ' + (input.treatment_name || 'Tratamiento recurrente') + '. Retraso: ' + overdue + ' días.';
    break;
  case 'recurring.reminder_48h':
  case 'recurring.reminder_24h':
    isNotificationEligible = true;
    templateCode = 'vet_recurring_session_reminder';
    alertSummary = 'Recordatorio de sesión ' + (input.session_number || 1) + '/' + (input.total_sessions || 1) + ' para ' + (input.pet_name || 'mascota') + ' (' + (input.treatment_name || 'Tratamiento') + ').';
    break;
  case 'recurring.plan_approved':
    isNotificationEligible = true;
    templateCode = 'vet_recurring_plan_welcome';
    alertSummary = 'Plan de cuidado recurrente aprobado por médico veterinario para ' + (input.pet_name || 'mascota') + ' (' + (input.total_sessions || 1) + ' sesiones).';
    break;
  default:
    isNotificationEligible = true;
    alertSummary = 'Evento de cuidado recurrente: ' + eventType + ' procesado para ' + (input.pet_name || 'paciente') + '.';
}

return {
  json: {
    event_type: eventType,
    plan_id: input.plan_id || 'rec-plan-default',
    treatment_name: input.treatment_name || 'Tratamiento Crónico',
    session_number: input.session_number || 1,
    total_sessions: input.total_sessions || 1,
    session_progress: (input.session_number || 1) + '/' + (input.total_sessions || 1),
    client_name: input.client_name || 'Tutor Vet Life',
    client_phone: input.client_phone || '+573128887766',
    pet_name: input.pet_name || 'Paciente',
    is_plan_approved: isApproved,
    overdue_days: overdue,
    is_adherence_risk: hasAdherenceRisk,
    is_notification_eligible: isNotificationEligible,
    template_code: templateCode,
    alert_summary: alertSummary,
    send_enabled: false,
    processed_at: new Date().toISOString()
  }
};
